importante reunir, por ejemplo, la siguiente
 — información: identificación, ubicación del lugar, fotos, coordenadas geográficas, ubicación del lugar,
tipo de flujo (abierto, cerrado), condiciones de acceso y técnica de muestreo. Si es necesario, describa', 'register', '{"title":"Probenahmestellen (puntos de muestreo, §4.2 / §5)","subtitle":"Je Probenahmestelle eine Zeile: Identifikation, Ort, Fotos, Koordinaten, Strömungsart, Zugang, Technik (§4.2) und die standortspezifischen Prüfungen nach §5","add_label":"+ Probenahmestelle","placement":"section","columns":[{"key":"kennung","label":"Identifikation","type":"text","required":true,"aria_label":"Identifikation der Probenahmestelle"},{"key":"location","label":"Ort","type":"text","aria_label":"Ubicación del lugar"},{"key":"photos","label":"Fotos","type":"boolean","aria_label":"Fotos vorhanden"},{"key":"coordinates","label":"Koordinaten","type":"text","aria_label":"Coordenadas geográficas"},{"key":"flow_type","label":"Strömungsart","type":"enum","options":["open","closed"],"option_labels":{"open":"abierto (offen)","closed":"cerrado (geschlossen)"},"aria_label":"Tipo de flujo"},{"key":"access","label":"Zugang","type":"text","aria_label":"Condiciones de acceso"},{"key":"technique","label":"Probenahmetechnik","type":"text","aria_label":"Técnica de muestreo"},{"key":"well_mixed","label":"gut durchmischt","type":"boolean","aria_label":"Abschnitt gut durchmischt und homogen (§4.2)"},{"key":"specific_site_type","label":"Standorttyp (§5)","type":"enum","required":true,"options":["sewer_channel_manhole","wwtp","industrial_site","cooling_system"],"option_labels":{"sewer_channel_manhole":"Alcantarillas, canales y pozos de registro (§5.1)","wwtp":"Planta de tratamiento de aguas residuales (§5.2)","industrial_site":"Emplazamiento industrial (§5.3)","cooling_system":"Sistema de refrigeración (§5.4)"},"discriminator":true,"aria_label":"Spezifischer Standorttyp"},{"key":"restriction_downstream_diameters","label":"Abstand stromab der Drossel (× Durchmesser)","type":"number","min":0,"visible_when":"specific_site_type == ''sewer_channel_manhole''","aria_label":"Abstand stromabwärts der Drossel in Rohrdurchmessern"},{"key":"sampling_depth_fraction","label":"Tiefe (Anteil der Wassertiefe)","type":"number","min":0,"max":1,"visible_when":"specific_site_type == ''sewer_channel_manhole''","placeholder":"0,33 … 0,5","aria_label":"Probenahmetiefe als Anteil der Wassertiefe"},{"key":"restriction_ok","label":"≥ 3 × Durchmesser","type":"derived","expr":"if(specific_site_type == ''sewer_channel_manhole'', if(restriction_downstream_diameters IS NULL, 0, if(restriction_downstream_diameters >= lookup(''S5_SITE'', ''sewer_channel_manhole'', ''restriction_min_diameters''), 1, 0)), 1)","display":"badge","value_labels":{"0":"§5.1 Abstand < 3 × D","1":"§5.1 Abstand ok"}},{"key":"depth_ok","label":"Tiefe 1/3 … 1/2","type":"derived","expr":"if(specific_site_type == ''sewer_channel_manhole'', if(sampling_depth_fraction IS NULL, 0, if(sampling_depth_fraction >= lookup(''S5_SITE'', ''sewer_channel_manhole'', ''depth_fraction_min'') AND sampling_depth_fraction <= lookup(''S5_SITE'', ''sewer_channel_manhole'', ''depth_fraction_max''), 1, 0)), 1)","display":"badge","value_labels":{"0":"§5.1 Tiefe außerhalb 1/3 … 1/2","1":"§5.1 Tiefe ok"}},{"key":"wwtp_objective","label":"Probenahmeziel Kläranlage","type":"enum","options":["whole_plant_performance","individual_unit_control"],"option_labels":{"whole_plant_performance":"control del rendimiento de toda la planta","individual_unit_control":"control de las unidades de tratamiento individuales"},"visible_when":"specific_site_type == ''wwtp''","aria_label":"Objetivo del muestreo en la planta"},{"key":"bypass_assessed","label":"Bypass-Ströme bewertet","type":"boolean","visible_when":"specific_site_type == ''wwtp''","aria_label":"Relevanz der Bypass-Ströme bewertet (§5.2)"},{"key":"cooling_type","label":"Kühlsystem","type":"enum","options":["once_through","primary_secondary","closed"],"option_labels":{"once_through":"flujo continuo","primary_secondary":"circuito primario / secundario","closed":"enfriamiento cerrado"},"visible_when":"specific_site_type == ''cooling_system''","aria_label":"Tipo de sistema de refrigeración"},{"key":"cooling_runoff_s","label":"Vorlaufzeit","type":"number","unit":"s","min":0,"visible_when":"specific_site_type == ''cooling_system''","aria_label":"Vorlaufzeit des Kühlwassers vor der Probenahme"},{"key":"upstream_of_biocide","label":"stromauf der Biozid-Dosierung","type":"boolean","visible_when":"specific_site_type == ''cooling_system''","aria_label":"Probenahmestelle stromaufwärts der Biozid-Dosierung"},{"key":"runoff_ok","label":"≥ 30 s","type":"derived","expr":"if(specific_site_type == ''cooling_system'', if(cooling_runoff_s IS NULL, 0, if(cooling_runoff_s >= lookup(''S5_SITE'', ''cooling_system'', ''runoff_min_s''), 1, 0)), 1)","display":"badge","value_labels":{"0":"§5.4 Vorlauf < 30 s","1":"§5.4 Vorlauf ok"}}],"footer":["stellen_count","stellen_site_fail"],"note":"información: identificación, ubicación del lugar, fotos, coordenadas geográficas, ubicación del lugar,\ntipo de flujo (abierto, cerrado), condiciones de acceso y técnica de muestreo. Si es necesario, describa Die Spalten nach dem Standorttyp zeigen nur die Prüfungen des gewählten §5-Abschnitts; die Einzelfelder derselben Angaben auf ISO-5667-10-02 / -04 bleiben bis zur Ratifizierung (iso5667_10-D-2 … D-11)."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
