SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'stellen_site_fail', 'Probenahmestellen mit nicht erfüllter §5-Prüfung (Abstand / Tiefe / Vorlauf)', 'number', NULL, false, '§5.1, §5.4', 'Plan 3: Ausgabe der Gleichung ISO-5667-10-02-D2 — Zeilen, deren Standorttyp-Prüfung (restriction_ok / depth_ok / runoff_ok) 0 ist; ein Gate darauf ist STAGED (iso5667_10-G-6).', 'imported_unverified', 'El punto de toma de muestras debe estar siempre situado aguas abajo de la restricción y, como
norma general, debe situarse al menos tres veces el diámetro de la tubería, o la anchura del canal,
aguas abajo de la restricción. La entrada de la sonda de muestreo debe orientarse preferentemente — En una instalación de muestreo (grifo de muestreo que permita la desinfección, preferiblemente por
flameo, y el vaciado) se dejará correr el agua durante al menos 30 s antes del muestreo. El muestreo', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'stellen_site_fail') AND w.code = 'ISO-5667-10-02' AND s.code = 'ISO-5667-10';
