INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'flow_cv_pct', 'Variationskoeffizient des Momentandurchflusses im Probenahmezeitraum (coeficiente de variación)', 'number', '%', false, '§7.2.2.4', 'Plan 3: Eingabe für die CTCV-Anwendungsbedingung — „cuando el caudal instantáneo del efluente varía poco en el tiempo (coeficiente de variación de la repetibilidad del 20 % por término medio …)“; Vergleich → ctcv_applicable (ISO-5667-10-05-D2).', 'imported_unverified', 'Este método puede aplicarse, por ejemplo, cuando el caudal instantáneo del efluente varía poco en
el tiempo (coeficiente de variación de la repetibilidad del 20 % por término medio y si la información
recogida demuestra que la carga contaminante no es muy variable durante el período de muestreo).', 'scalar', NULL, NULL, 'composite_mode == ''CTCV''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'flow_cv_pct') AND w.code = 'ISO-5667-10-05' AND s.code = 'ISO-5667-10';
