SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'ctcv_cv_max', 'Zulässiger Variationskoeffizient für CTCV nach §7.2.2.4', 'number', '%', false, '§7.2.2.4', 'Plan 3: Ausgabe der Gleichung ISO-5667-10-05-D1 (S7_2_2_4.cv_max_pct = 20).', 'imported_unverified', 'Este método puede aplicarse, por ejemplo, cuando el caudal instantáneo del efluente varía poco en
el tiempo (coeficiente de variación de la repetibilidad del 20 % por término medio y si la información
recogida demuestra que la carga contaminante no es muy variable durante el período de muestreo).', 'derived', NULL, NULL, 'composite_mode == ''CTCV''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'ctcv_cv_max') AND w.code = 'ISO-5667-10-05' AND s.code = 'ISO-5667-10';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'ctcv_applicable', 'CTCV-Bedingung erfüllt (1 = Durchfluss variiert wenig, 0 = nicht)', 'number', NULL, false, '§7.2.2.4', 'Plan 3: Ausgabe der Gleichung ISO-5667-10-05-D2 — flow_cv_pct ≤ 20 %; ein Gate darauf ist nicht gestellt („puede aplicarse … por ejemplo“, Anhaltswert).', 'imported_unverified', 'Este método puede aplicarse, por ejemplo, cuando el caudal instantáneo del efluente varía poco en
el tiempo (coeficiente de variación de la repetibilidad del 20 % por término medio y si la información
recogida demuestra que la carga contaminante no es muy variable durante el período de muestreo). — En este caso, como el caudal no es relevante para los compuestos ponderados por tiempo, se
recomienda que las muestras se recojan en una sola botella para evitar la etapa de transferencia.', 'derived', NULL, NULL, 'composite_mode == ''CTCV''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'ctcv_applicable') AND w.code = 'ISO-5667-10-05' AND s.code = 'ISO-5667-10';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'composite_duration_band', 'Dauer der Mischprobe (2 h / 24 h, §7.2.1)', 'enum', NULL, false, '§7.2.1', 'Plan 3: Treiber des Höchstintervalls zwischen Einzelproben — 5 min bei der 2-h-Mischprobe, 30 min bei der 24-h-Mischprobe (füllt composite_interval_max); CR-016 prüft heute nur die 30 min — Umstellung STAGED (iso5667_10-G-3).', 'imported_unverified', 'continuo es el más adecuado. Para el muestreo discontinuo, seleccione los intervalos más cortos
posibles entre las muestras individuales. No deben superar los 5 minutos para la muestra mixta de 2
horas y los 30 minutos para la muestra mixta de 24 horas. — La duración del muestreo depende de los parámetros especificados en los permisos de vertido de
aguas. La información sobre la duración del muestreo (muestra aleatoria, muestra aleatoria
cualificada, muestra mixta de 2 h, muestra compuesta de 24 h) se basa en la legislación (por ejemplo,
los anexos relacionados con el origen de las aguas residuales de la Ordenanza de Aguas Residuales).', 'select_one', NULL, NULL, 'main_sampling_type == ''composite''', '[{"value":"h2","label_de":"muestra mixta de 2 horas (Mischprobe 2 h)","order_index":0},{"value":"h24","label_de":"muestra mixta de 24 horas (Mischprobe 24 h)","order_index":1}]'::jsonb, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'composite_duration_band') AND w.code = 'ISO-5667-10-06' AND s.code = 'ISO-5667-10';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'composite_interval_max', 'Höchstintervall zwischen Einzelproben nach §7.2.1 (2 h → 5 min, 24 h → 30 min)', 'number', 'min', false, '§7.2.1', 'Plan 3: aus der Dauer der Mischprobe gefüllt (locked — „No deben superar“); das Eingabefeld composite_interval (CR-016) bleibt — Vergleich composite_interval ≤ composite_interval_max STAGED (iso5667_10-G-3).', 'imported_unverified', 'continuo es el más adecuado. Para el muestreo discontinuo, seleccione los intervalos más cortos
posibles entre las muestras individuales. No deben superar los 5 minutos para la muestra mixta de 2
horas y los 30 minutos para la muestra mixta de 24 horas.', 'lookup_fill', '{"source_label":"§7.2.1"}'::jsonb, '{"table_code":"S7_2_1","role":"limit","keys":[{"column":"duration","from_symbol":"composite_duration_band"}],"value":"max_interval_min"}'::jsonb, 'main_sampling_type == ''composite''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'composite_interval_max') AND w.code = 'ISO-5667-10-06' AND s.code = 'ISO-5667-10';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'suction_velocity_min', 'Mindest-Ansauggeschwindigkeit nach §7.2.2.1 (0,5 m/s; 0,3 m/s ab 12 mm Innendurchmesser, NOTA 1)', 'number', 'm/s', false, '§7.2.2.1', 'Plan 3: Ausgabe der Gleichung ISO-5667-10-06-D4 (S7_2_2_1_TUBE nach dem Innendurchmesser des Ansaugschlauchs); CR-017 prüft heute fest 0,5 m/s — Umstellung STAGED (iso5667_10-G-4).', 'imported_unverified', '- Velocidad de aspiración: no debe ser inferior a 0,5 m/s para evitar la segregación de la materia en
suspensión en el — NOTA 1 Pueden ser posibles velocidades de aspiración inferiores si se demuestra que son
satisfactorias. Un ejemplo es cuando el diámetro interno del tubo de aspiración es de 12 mm o más,
en cuyo caso se ha demostrado que una velocidad de aspiración de 0,3 m/s es aceptable[5].', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'suction_velocity_min') AND w.code = 'ISO-5667-10-06' AND s.code = 'ISO-5667-10';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'flaschen_ctcv', 'Einzelflaschen n mit M3n und Vn nach Fórmula (3)', 'json', NULL, false, '§7.2.2.3, Fórmula (3)', 'Plan 3: Zeilen je Flasche mit Vn = Vfinal · (M3n / M3total) (Fórmula 3, Legende L1017–L1023); Σ Vn → v_n_sum (ISO-5667-10-06-D1), Σ M3n → m3_n_sum (-D2), Anzahl → flaschen_count (-D3). Die prod-Gleichung 3 (V_n aus einem M3_n) bleibt verifiziert; IF-Guard von CR-019 STAGED (iso5667_10-G-7).', 'imported_unverified', 'Cuando el muestreador automático no puede conectarse al caudalímetro (por incompatibilidad de
los equipos o por una distancia demasiado grande entre ambos dispositivos), cuando el caudal y/o la
composición del efluente son variables o por exigencias legales, se puede realizar un muestreo
ponderado en el tiempo. Por lo tanto, es necesario construir la muestra compuesta (sujeto al uso de
un muestreador automático de botellas múltiples). —                                                                   𝑀3 𝑛
                                              𝑉𝑛 = [𝑉𝑓𝑖𝑛𝑎𝑙 𝑥 (            )]
                                                                 𝑀3 𝑡𝑜𝑡𝑎𝑙

Vn: volumen de la muestra (ml) a tomar en la botella n

Vfinal: volumen total (ml) de las botellas del laboratorio

M3total: volumen total descargado (M3)

M3n: volumen descargado durante el muestreo de la botella n (M3)', 'register', '{"title":"Einzelflaschen der zeitproportionalen Mischprobe (Fórmula 3, §7.2.2.3)","subtitle":"Je Flasche n eine Zeile: abgegebenes Volumen M3n; Vn = Vfinal · (M3n / M3total) aus Vfinal und M3total dieses Arbeitsblatts","add_label":"+ Flasche","placement":"section","columns":[{"key":"n","label":"Flasche n","type":"number","required":true,"min":1,"aria_label":"Flaschennummer n"},{"key":"m3_n","label":"M3n","type":"number","unit":"m³","required":true,"min":0,"aria_label":"Abgegebenes Volumen während der Flasche n M3n"},{"key":"v_n","label":"Vn","type":"derived","expr":"V_final * m3_n / M3_total"}],"footer":["flaschen_count","v_n_sum","m3_n_sum"],"note":"La metodología para obtener una muestra media reconstituida en relación con el flujo es la siguiente.\nEl operario de muestreo homogeneiza cada botella individual y toma, en cada botella individual, un\nvolumen proporcional al caudal. Toma el mayor volumen en la botella individual más llena.\n\nPara las demás botellas individuales, toma el volumen (ml) que debe tomarse (Vn) en la botella. n es\nun porcentaje relativo al volumen total (Fórmula 3): Σ Vn = Vfinal und Σ M3n = M3total prüfen (Fußzeile); bei der Einflaschen-Variante des §7.2.2.4 bleibt das Register leer (iso5667_10-J-2). Die Einzelfelder M3_n / V_n bleiben (iso5667_10-D-15 / D-16)."}'::jsonb, NULL, 'composite_mode == ''CTCV''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'flaschen_ctcv') AND w.code = 'ISO-5667-10-06' AND s.code = 'ISO-5667-10';
