SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'm3_n_sum', 'Σ M3n über alle Flaschen (soll = M3total)', 'number', 'm³', false, '§7.2.2.3, Fórmula (3)', 'Plan 3: Ausgabe der Gleichung ISO-5667-10-06-D2 (sum_rows über flaschen_ctcv.m3_n); „M3total: volumen total descargado (M3)“.', 'imported_unverified', 'Vn: volumen de la muestra (ml) a tomar en la botella n

