un muestreador automático de botellas múltiples).', 'derived', NULL, NULL, 'composite_mode == ''CTCV''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
