INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'event_trigger_criterion', 'Auslösekriterium der ereignisgesteuerten Probenahme (criterio predeterminado: precipitaciones, conductividad, pH, sustancia contaminante …)', 'text', NULL, false, '§3.10, §7.3.4', 'Plan 3: Freitext für das vorbestimmte Kriterium, das die Probenahme auslöst (§3.10) — nur bei ereignisgesteuerter Probenahme sichtbar; die Norm druckt Beispiele, keine feste Optionsliste.', 'imported_unverified', '3.10. Muestreo desencadenado por un evento
El muestreo que se desencadena porque se ha cumplido un criterio predeterminado (por ejemplo,
precipitaciones, cambios en conductividad eléctrica, el pH o la introducción de una sustancia
contaminante), cuando las muestras deben tomarse manualmente o con equipos automáticos. — 7.3.4 Muestreo automático, de inicio remoto o activado por eventos
El muestreo automático activado por eventos, basado en la monitorización en línea en tiempo real
de los parámetros de las aguas residuales, aumenta la posibilidad de obtener una muestra
representativa de la calidad real de las aguas residuales en ese momento específico.', 'scalar', NULL, NULL, 'event_triggered_sampling == true', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'event_trigger_criterion') AND w.code = 'ISO-5667-10-06' AND s.code = 'ISO-5667-10';
UPDATE fields f SET widget = 'attestation', ui_config = NULL, lookup = NULL, visible_when = 'representativeness_mode == ''in_storage''' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'tank_mixing_maintained' AND w.code = 'ISO-5667-10-06' AND s.code = 'ISO-5667-10' AND f.active;
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'probenahmegeraete', 'Probenahmegeräte (je Gerät: Bauart, Pumpentechnologie, Einheitsvolumen, Kühlung, Material, Reinigung)', 'json', NULL, false, '§8.2, §8.3.1, §7.2.2.1', 'Plan 3: Zeilen je Probenahmegerät; das Mindest-Einheitsvolumen je Pumpentechnologie (S7_2_2_1_PUMP: 50 ml Vakuum, 25 ml Inline-Kolben) wird je Zeile geprüft; Anzahl → geraete_count (ISO-5667-10-07-D1), Zeilen unter dem Minimum → geraete_unit_volume_fail (-D2). CR-018 prüft unit_volume auf ISO-5667-10-06 fest gegen 25 ml — Umstellung nach Pumpentechnologie STAGED (iso5667_10-G-5).', 'imported_unverified', 'Los muestreadores automáticos pueden ser fijos o portátiles y también pueden estar equipados con
una cámara refrigerada. — El muestreo de los sistemas de bombeo puede realizarse mediante diferentes tecnologías [por
ejemplo, mediante una bomba de vacío (VAP), mediante una bomba peristáltica (PP), mediante un
émbolo en línea o utilizando sistemas de bombeo externos]. Las ventajas e inconvenientes de los dos
tipos principales de muestreadores se presentan en el Anexo F. — - debe ser adecuado para garantizar un muestreo representativo (por ejemplo, al menos 50 ml para
la bomba de vacío o 25 ml para el émbolo en línea);', 'register', '{"title":"Probenahmegeräte (muestreadores, §8.2 / §8.3)","subtitle":"Je Gerät eine Zeile: Bauart, Pumpentechnologie, Einheitsvolumen gegen das gedruckte Minimum (§7.2.2.1: 50 ml Vakuumpumpe, 25 ml Inline-Kolben), Kühlung, Material, Reinigung","add_label":"+ Gerät","placement":"section","columns":[{"key":"label","label":"Gerät","type":"text","required":true,"aria_label":"Bezeichnung des Geräts"},{"key":"mobility","label":"Bauart","type":"enum","options":["fixed","portable"],"option_labels":{"fixed":"fijo (fest)","portable":"portátil (tragbar)"},"aria_label":"Bauart fest / tragbar"},{"key":"pump_technology","label":"Pumpentechnologie","type":"enum","required":true,"options":["vacuum","peristaltic","inline_piston","external"],"option_labels":{"vacuum":"bomba de vacío (VAP)","peristaltic":"bomba peristáltica (PP)","inline_piston":"émbolo en línea","external":"sistemas de bombeo externos"},"discriminator":true,"aria_label":"Pumpentechnologie"},{"key":"unit_volume_ml","label":"Einheitsvolumen","type":"number","unit":"ml","min":0,"aria_label":"Einheitsvolumen des Geräts"},{"key":"unit_volume_min","label":"Minimum §7.2.2.1","type":"derived","expr":"lookup(''S7_2_2_1_PUMP'', pump_technology, ''min_unit_volume_ml'')"},{"key":"unit_volume_ok","label":"Einheitsvolumen","type":"derived","expr":"if(unit_volume_min IS NULL, 1, if(unit_volume_ml IS NULL, 0, if(unit_volume_ml >= unit_volume_min, 1, 0)))","display":"badge","value_labels":{"0":"Einheitsvolumen unter dem Minimum oder nicht eingetragen","1":"Einheitsvolumen ≥ Minimum (oder kein gedruckter Mindestwert)"}},{"key":"refrigerated","label":"gekühlt","type":"boolean","aria_label":"Gerät mit Kühlkammer (§8.2)"},{"key":"material_compatible","label":"Material kompatibel","type":"boolean","aria_label":"Material kompatibel mit dem Zielparameter (§8.2 / Anexo E)"},{"key":"cleaned_checked","label":"gereinigt & geprüft","type":"boolean","aria_label":"Vor der Probenahme gereinigt (Anexo C) und geprüft (10.3)"}],"footer":["geraete_count","geraete_unit_volume_fail"],"note":"- debe ser adecuado para garantizar un muestreo representativo (por ejemplo, al menos 50 ml para\nla bomba de vacío o 25 ml para el émbolo en línea); Für bomba peristáltica und sistemas de bombeo externos druckt die Norm kein Mindestvolumen (iso5667_10-E-1) — die Zeile gilt dann als nicht prüfbar (Badge 1). Die Einzelfelder sampler_mobility / pump_technology / sampler_refrigerated / material_compatible / equipment_cleaned_checked bleiben (iso5667_10-D-17 … D-21)."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'probenahmegeraete') AND w.code = 'ISO-5667-10-07' AND s.code = 'ISO-5667-10';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'geraete_count', 'Anzahl erfasster Probenahmegeräte', 'number', NULL, false, '§8.2', 'Plan 3: Ausgabe der Gleichung ISO-5667-10-07-D1 (count_rows über probenahmegeraete).', 'imported_unverified', 'Los muestreadores automáticos pueden ser fijos o portátiles y también pueden estar equipados con
una cámara refrigerada.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'geraete_count') AND w.code = 'ISO-5667-10-07' AND s.code = 'ISO-5667-10';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'geraete_unit_volume_fail', 'Geräte mit Einheitsvolumen unter dem gedruckten Minimum (§7.2.2.1)', 'number', NULL, false, '§7.2.2.1', 'Plan 3: Ausgabe der Gleichung ISO-5667-10-07-D2 (count_rows über probenahmegeraete, unit_volume_ok == 0); ein Gate darauf ist STAGED (iso5667_10-G-5).', 'imported_unverified', '- Volumen de la unidad:

- debe ser adecuado para garantizar un muestreo representativo (por ejemplo, al menos 50 ml para
la bomba de vacío o 25 ml para el émbolo en línea);', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'geraete_unit_volume_fail') AND w.code = 'ISO-5667-10-07' AND s.code = 'ISO-5667-10';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'homogenizer_mechanical_required', 'Mechanischer / magnetischer Homogenisierer erforderlich (1 = Volumen > 5 l, 0 = ≤ 5 l Labormethode)', 'number', NULL, false, '§9.1', 'Plan 3: Ausgabe der Gleichung ISO-5667-10-08-D1 (collected_volume > S9_1.threshold_l = 5 l ⇒ 1); das Gate „homogenizer_type == mechanical“ unter dieser Bedingung ist STAGED (iso5667_10-G-2, „deberían utilizarse“ ⇒ warn).', 'imported_unverified', 'Para volúmenes de muestra mayores (por ejemplo, > 5 l), los homogeneizadores con recipientes de
muestra transportables y

con agitador magnético o mecánico deberían utilizarse. — Para volúmenes inferiores recogidos (≤5 l), puede aplicarse el método de laboratorio (por ejemplo,
agitación manual, mezcla con varillas, etc.).', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'homogenizer_mechanical_required') AND w.code = 'ISO-5667-10-08' AND s.code = 'ISO-5667-10';
COMMIT;
